#!/bin/sh
# Builds the password file from one env var per account (MQTT_PASS_<USERNAME>), then starts
# the broker. The account list is generated by scripts/gen_lab.py into accounts.txt.
set -eu
f=/tmp/passwd
: > "$f"
chmod 0700 "$f"
while IFS= read -r u; do
  [ -z "$u" ] && continue
  var="MQTT_PASS_$(printf '%s' "$u" | tr 'a-z-' 'A-Z_')"
  pw=$(printenv "$var" || true)
  if [ -z "$pw" ]; then
    echo "missing password env $var for account $u" >&2
    exit 1
  fi
  mosquitto_passwd -b "$f" "$u" "$pw"
done < /mosquitto/config/accounts.txt
chown mosquitto:mosquitto "$f"
exec mosquitto -c /mosquitto/config/mosquitto.conf
